-- steps (14 per lesson)
INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e31c4456-b229-5fef-9e9b-33f1cf41159b', 'b6ff00b4-51cd-5d0f-bfaf-4e056ec1a063', 'text', 'Vocabulary', '{"text": "## Classroom Basics\n\n**Class** — A group of students learning together.\n_My English class is very fun._\n\n**School** — A place for education.\n_This school is near my home._\n\n**Student** — A person who learns at a school.\n_I am a student of English._\n\n**Teacher** — A person who helps students learn.\n_My teacher is very kind._\n\n**Learn** — To gain new knowledge.\n_I want to learn new words._\n\n**Study** — To read and work on lessons.\n_I study for one hour daily._\n\n**Room** — The specific place where classes happen.\n_The classroom is on the first floor._\n\n**Desk** — A table for writing and study.\n_Sit at your desk, please._\n\n**Chair** — Furniture for sitting.\n_Take a chair and sit down._\n\n**Book** — Printed pages for reading.\n_Open your book to page ten._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('58315b24-ff73-5f25-8b1a-ebfe4a7b4304', 'b6ff00b4-51cd-5d0f-bfaf-4e056ec1a063', 'match_pairs', 'Match the pairs', '{"instruction": "Match the word to its Russian translation", "pairs": [{"left": "Class", "right": "класс"}, {"left": "School", "right": "школа"}, {"left": "Student", "right": "студент"}, {"left": "Teacher", "right": "учитель"}, {"left": "Learn", "right": "учить"}, {"left": "Study", "right": "учить"}, {"left": "Room", "right": "классная комната"}, {"left": "Desk", "right": "письменный стол"}, {"left": "Chair", "right": "стул"}, {"left": "Book", "right": "книга"}]}', 1, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
