INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('bb2efc2c-dccc-52ff-8303-d41b20be334f', '0d96a7fc-e4ca-5464-956d-8ebf3814d49e', 'text', 'Vocabulary', '{"text": "## Writing & Supplies\n\n**Pen** — A tool for writing with ink.\n_Do you have a blue pen?_\n\n**Pencil** — A tool for writing with graphite.\n_I use a pencil for my math._\n\n**Paper** — Thin material for writing on.\n_I need some clean paper._\n\n**Write** — Using a pen to create words.\n_Please write your name here._\n\n**Note** — A short record of information.\n_Take a note of these words._\n\n**Bag** — A container for school supplies.\n_Put your pens in your bag._\n\n**Eraser** — Used to remove pencil marks.\n_I need an eraser to fix this._\n\n**Ruler** — Used for drawing straight lines.\n_Use a ruler for this line._\n\n**Sharp** — Having a fine point (like a pencil).\n_My pencil is not sharp._\n\n**Use** — To employ a tool for a task.\n_Use your pen for the test._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
