INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c888af84-41df-59bf-9db9-a84febb353c2', 'ac0a3ffb-9482-5f63-86bd-04da47d2af2d', 'text', 'Vocabulary', '{"text": "## The Lesson\n\n**Lesson** — A specific period of teaching.\n_The English lesson starts at nine._\n\n**Teach** — Giving information to students.\n_The teacher will teach us grammar._\n\n**Listen** — Paying attention to sounds/speech.\n_Listen to the teacher carefully._\n\n**Talk** — Speaking with others.\n_Do not talk during the lesson._\n\n**Read** — Looking at and understanding text.\n_We read a story today._\n\n**Speak** — Using your voice for language.\n_Speak English in the class._\n\n**Answer** — A response to a question.\n_Give me the correct answer._\n\n**Question** — Asking for information.\n_Do you have a question?_\n\n**Page** — One side of a book sheet.\n_Look at the next page._\n\n**Easy** — Not difficult to do.\n_This lesson is very easy._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
