INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('cd79708c-7787-516b-abe1-2ddf1715b2f0', '4244324b-2b4d-51e5-b3bc-dfbdda0af844', 'text', 'Vocabulary', '{"text": "## Homework\n\n**Homework** — Study tasks done at home.\n_Do your homework after school._\n\n**Task** — A piece of work to be done.\n_I have a difficult task._\n\n**Finish** — To complete something.\n_Finish your work before dinner._\n\n**Home** — Where you live and relax.\n_I study at home._\n\n**Hard** — Difficult or requires effort.\n_The homework is a bit hard._\n\n**Help** — Getting support.\n_Can you help me with this?_\n\n**Work** — Any effort or task.\n_The work is almost finished._\n\n**Easy** — Simple to complete.\n_This task is quite easy._\n\n**Do** — The action of performing tasks.\n_Do your best on the work._\n\n**Time** — Hours spent studying.\n_I need more time for this._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
