INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('ac041495-c107-53cb-b770-4f47dc6e9e43', '93f38f63-9682-5690-9122-0809e70db36f', 'text', 'Vocabulary', '{"text": "## Tests & Grades\n\n**Test / Exam** — A way to check your knowledge.\n_We have a math test today._\n\n**Grade** — The score you receive (A, B, C).\n_I want a good grade._\n\n**Pass** — Getting a high enough score.\n_I hope to pass the exam._\n\n**Fail** — Not getting a high score.\n_I do not want to fail._\n\n**Result** — The final outcome.\n_The result is very good._\n\n**Hard** — Needing lots of study.\n_The test was very hard._\n\n**Study** — Preparing for the test.\n_Study for the exam tonight._\n\n**Correct** — Being right.\n_All your answers are correct._\n\n**Score** — The points you earned.\n_My score is eighty._\n\n**Good** — Positive result.\n_You did a good job!_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
