VALUES ('8dcfe45e-5a0b-5a51-97f7-57db31438f2e', '12978e83-3b85-5302-85d0-9204ef5dec60', 'text', 'Vocabulary', '{"text": "## Using the Computer\n\n**Computer** — A digital machine for work.\n_Use the computer for your work._\n\n**Internet** — The worldwide network.\n_I search the internet for words._\n\n**Web** — Online pages.\n_Find the school web site._\n\n**Email** — Sending digital messages.\n_Send your homework by email._\n\n**Search** — Looking for information.\n_Search for the meaning here._\n\n**Type** — Using a keyboard.\n_Type the words on the screen._\n\n**Screen** — The monitor display.\n_The screen is very bright._\n\n**Save** — Keeping your digital file.\n_Save your file now._\n\n**File** — A digital document.\n_Open the English class file._\n\n**Fast** — High speed.\n_The internet is very fast._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
