INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('b07d297a-ee81-5281-909e-efc614d8c467', 'ece3816f-2d8e-53d8-bff4-8e17d2858e65', 'text', 'Vocabulary', '{"text": "## Asking for Help\n\n**Help** — Asking for assistance.\n_Can you help me, please?_\n\n**Understand** — Getting the meaning.\n_I do not understand this._\n\n**Meaning** — The definition of a word.\n_What is the meaning here?_\n\n**Question** — Asking for clarity.\n_I have a small question._\n\n**Repeat** — Saying it again.\n_Can you repeat that, please?_\n\n**Slow** — Not fast speed.\n_Please speak a bit slow._\n\n**Explain** — Making it clear.\n_Can you explain this again?_\n\n**Word** — A unit of language.\n_I do not know this word._\n\n**Speak** — Vocal communication.\n_Speak slowly, please._\n\n**Clear** — Easy to understand.\n_Is that clear now?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
