VALUES ('65097d01-5d22-5fc6-833b-1a408275ddb1', '434af20e-e16a-58ad-91f4-ff7c1e2cb0fb', 'text', 'Vocabulary', '{"text": "## Classroom Rules\n\n**Rule** — A guideline for behavior.\n_Follow the classroom rules._\n\n**Quiet** — Keeping sound down.\n_Be quiet during the lesson._\n\n**Listen** — Paying attention.\n_Listen to the teacher._\n\n**Late** — Coming after time.\n_Do not be late today._\n\n**Hand** — Lifting to speak.\n_Raise your hand to talk._\n\n**Respect** — Being kind to others.\n_Respect your classmates._\n\n**Clean** — Not messy.\n_Keep your desk clean._\n\n**Right** — Doing the correct thing.\n_It is right to listen._\n\n**Help** — Assisting peers.\n_Help your friend today._\n\n**Sit** — Resting in your chair.\n_Sit in your seat._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
