INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('4c951ffd-646f-5133-8c96-10c932f21347', '89ada5c3-64ff-53a7-8cd2-1fb6d6ee7aba', 'text', 'Vocabulary', '{"text": "## After School\n\n**School** — Ending the day.\n_School ends at three._\n\n**Home** — Going to your house.\n_I go home now._\n\n**Friend** — Someone you like.\n_I walk home with a friend._\n\n**Play** — Having fun activity.\n_We play in the park._\n\n**Rest** — Relaxing after work.\n_I need to rest now._\n\n**Study** — More learning.\n_I study for an hour._\n\n**Happy** — Feeling glad.\n_I am happy today._\n\n**Free** — Not busy.\n_I am free this evening._\n\n**Tomorrow** — The next day.\n_See you again tomorrow!_\n\n**Finish** — Ending the day.\n_I finish my school day._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
