INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('4706473a-fc70-591e-baeb-108c7256db52', '28c26cf5-1d0c-5548-85ca-12dbc3319168', 'text', 'Vocabulary', '{"text": "## Books and Reading\n\n**Textbook** — The main book used for a class.\n_Please open your textbook to page twenty._\n\n**Read** — Looking at words to understand them.\n_I like to read English books._\n\n**Story** — A narrative in a book.\n_The story in the book is interesting._\n\n**Page** — One side of a leaf of paper in a book.\n_Turn to the next page._\n\n**Chapter** — A main section of a book.\n_Read chapter one for homework._\n\n**Meaning** — The definition of what you read.\n_What is the meaning of this word?_\n\n**Library** — A place with many books.\n_I go to the library to study._\n\n**Borrow** — To take a book for a short time.\n_Can I borrow this book?_\n\n**Return** — To give a book back.\n_Return the book to the library._\n\n**Quiet** — Necessary for reading.\n_Please be quiet in the library._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
