INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d6801062-bf4d-55d8-8efe-b331497f09ae', '65e4e705-fed8-5539-acf8-bd695e736db6', 'text', 'Vocabulary', '{"text": "## The Classroom Environment\n\n**Board** — The large surface for the teacher to write on.\n_Look at the white board, please._\n\n**Marker** — A pen used for the white board.\n_Where is the board marker?_\n\n**Clean** — To wipe the board.\n_Can you clean the board?_\n\n**Wall** — The side of the room.\n_Look at the map on the wall._\n\n**Map** — A visual of the world or country.\n_The world map is big._\n\n**Light** — The illumination in the room.\n_Turn on the light, please._\n\n**Door** — The entrance/exit of the room.\n_Close the door quietly._\n\n**Window** — The glass opening for light.\n_Open the window for fresh air._\n\n**Seat** — Where a student sits.\n_Is this seat free?_\n\n**Place** — The location in the classroom.\n_Find your place in the room._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
