INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('6dc8db8e-b75c-5e43-acec-4f4bdeb25d18', 'bcdbebc5-410c-59dc-af20-5fb886a2d274', 'text', 'Vocabulary', '{"text": "## Asking and Answering\n\n**Ask** — To seek information.\n_You can ask the teacher._\n\n**Answer** — The response given.\n_Write the answer in your notebook._\n\n**Question** — Something you want to know.\n_Do you have a question?_\n\n**Correct** — Being right.\n_That answer is correct._\n\n**Wrong** — Not being right.\n_That answer is a bit wrong._\n\n**Help** — Giving assistance.\n_Can I help you with this?_\n\n**Explain** — To make something easy to understand.\n_Please explain the rule again._\n\n**Repeat** — To say something again.\n_Can you repeat the question?_\n\n**Slow** — Not fast.\n_Please speak a bit slower._\n\n**Understand** — Getting the meaning.\n_Do you understand the lesson?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
