INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('fd3ffc8a-b81c-5bc4-bece-9ec9f4a94f17', '987d24f8-cf98-527b-9dd5-01f8b1ee1876', 'text', 'Vocabulary', '{"text": "## Studying Together\n\n**Partner** — A person you work with.\n_Work with a partner, please._\n\n**Group** — More than two people working together.\n_Form a small group._\n\n**Talk** — Speaking with others.\n_Talk about the lesson._\n\n**Discuss** — To share ideas.\n_Discuss the answer with your friend._\n\n**Share** — Giving parts of your work.\n_Share your notes with me._\n\n**Team** — A group working for a goal.\n_Our team is very fast._\n\n**Work** — Doing a task together.\n_We work well together._\n\n**Friend** — A person you like.\n_My friend helps me study._\n\n**Classmate** — A student in your class.\n_My classmate is from Tajikistan._\n\n**Same** — Exactly alike.\n_We have the same book._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
