INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('2edb79ca-6bfa-5d81-a7f6-62c02b233142', '73fa6600-bffd-55d3-9ffd-a35f33eebb2d', 'text', 'Vocabulary', '{"text": "## Vocabulary and Grammar\n\n**Word** — A single unit of language.\n_How do you spell this word?_\n\n**Spelling** — Using letters in the right order.\n_Check your spelling._\n\n**Grammar** — The rules of language.\n_English grammar is interesting._\n\n**Sentence** — A group of words making sense.\n_Write a short sentence._\n\n**Meaning** — The definition.\n_What is the meaning of ''apple''?_\n\n**Translate** — Changing language.\n_Translate this word into Tajik._\n\n**Language** — English, Tajik, etc.\n_English is a useful language._\n\n**Dictionary** — A book of word definitions.\n_Look it up in your dictionary._\n\n**Note** — Writing down information.\n_Take a note in your book._\n\n**Correct** — Fixing mistakes.\n_Correct the grammar mistake._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
