INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d54beb13-2d01-50e2-98ed-ad4a49bf29ad', '1a0cd008-a073-55c2-97ab-af42d096a082', 'text', 'Vocabulary', '{"text": "## Classroom Communication\n\n**Excuse** — Used to get attention.\n_Excuse me, teacher._\n\n**Sorry** — Apologizing.\n_I am sorry I am late._\n\n**Please** — Being polite.\n_Can I have a pen, please?_\n\n**Thanks** — Showing gratitude.\n_Thanks for the help._\n\n**Ready** — Prepared.\n_Are you ready for the test?_\n\n**Finish** — Completing a task.\n_Did you finish your work?_\n\n**Wait** — Staying in place.\n_Please wait for me._\n\n**Go** — Moving away.\n_You can go now._\n\n**Come** — Moving toward.\n_Come here, please._\n\n**Start** — The beginning.\n_We will start the lesson._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
