INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('3c5fa368-144f-5cc0-bac8-a32ae6377305', '5001524f-7a95-5391-bdb2-e53928b1bee4', 'text', 'Vocabulary', '{"text": "## Using Paper and Notebooks\n\n**Notebook** — A book for writing notes.\n_Open your notebook now._\n\n**Paper** — A sheet for writing.\n_I need one sheet of paper._\n\n**Write** — The action of using a pen.\n_Write your name on the paper._\n\n**Pen** — Instrument for ink.\n_Use a black pen._\n\n**Pencil** — Instrument for lead.\n_Use a pencil for the test._\n\n**Eraser** — Removing mistakes.\n_Where is my eraser?_\n\n**Mistake** — A wrong action.\n_I made a small mistake._\n\n**Clean** — No marks.\n_Keep the page clean._\n\n**Line** — A straight mark.\n_Write on the line._\n\n**Top** — The highest part of the page.\n_Write your name at the top._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
