INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('5030dfba-bc70-52ab-a904-7647ff4d49b3', '08d43cb7-fe68-5fc6-80ea-a6702ca2b8c3', 'text', 'Vocabulary', '{"text": "## Time and Scheduling\n\n**Time** — The hour of the day.\n_What time is the class?_\n\n**Hour** — Sixty minutes.\n_We study for one hour._\n\n**Minute** — Smaller unit of time.\n_Five minutes to start._\n\n**Day** — Today, tomorrow, etc.\n_What day is today?_\n\n**Week** — Seven days.\n_English class is every week._\n\n**Lesson** — Scheduled teaching.\n_The lesson ends soon._\n\n**Early** — Before the time.\n_You are very early._\n\n**Late** — After the time.\n_Do not be late today._\n\n**Wait** — Passing time.\n_We wait for the teacher._\n\n**Soon** — In a short time.\n_The test starts soon._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
