VALUES ('1fc85bb5-b4df-5483-86d4-402c6a2c3227', '9db6fd69-9e1d-5240-97d3-5ccf9a142b2f', 'text', 'Vocabulary', '{"text": "## School Equipment\n\n**Desk** — Table for students.\n_Sit at your desk._\n\n**Chair** — Seat for students.\n_This chair is comfortable._\n\n**Bag** — Carrying supplies.\n_Is your bag heavy?_\n\n**Computer** — Electronic device.\n_The computer is on the desk._\n\n**Screen** — Monitor surface.\n_Look at the computer screen._\n\n**Map** — Visual aid.\n_Where is the city map?_\n\n**Light** — Illumination.\n_Turn off the light._\n\n**Door** — Room entrance.\n_Open the classroom door._\n\n**Window** — View area.\n_The window is very large._\n\n**Floor** — Bottom of the room.\n_Keep the floor clean._\n"}', 0, NOW(), NOW())
