VALUES ('ea339e5b-c0a9-563f-ba64-8bcdab2c9415', '12718d0a-f2f8-5202-9473-f069db481469', 'text', 'Vocabulary', '{"text": "## Success and Progress\n\n**Learn** — Gaining skills.\n_You learn fast today._\n\n**Study** — Effort to learn.\n_Study well for your future._\n\n**Good** — Positive result.\n_Good work, students._\n\n**Great** — Very positive.\n_That is a great answer._\n\n**Pass** — Succeeding.\n_You will pass the test._\n\n**Try** — Making an effort.\n_Try to speak English._\n\n**Well** — High quality.\n_You speak very well._\n\n**Future** — Time ahead.\n_English is good for your future._\n\n**Happy** — Pleased.\n_I am happy with your work._\n\n**Finish** — Completion.\n_We finish this goal today._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
