INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e107f5cc-77d5-5d00-8534-e73fb9163d56', 'e984f100-b658-5f93-87d5-381341541ea5', 'text', 'Vocabulary', '{"text": "## Digital Tools\n\n**Laptop** — A portable computer for students.\n_Use your laptop for the lesson._\n\n**Tablet** — A small touchscreen computer.\n_Read the book on your tablet._\n\n**Online** — Connected to the internet.\n_We have an online class today._\n\n**Website** — A location on the internet.\n_Visit our school website now._\n\n**Search** — Looking for information online.\n_Search for the meaning of this word._\n\n**Click** — Pressing a button on a mouse or screen.\n_Click here to start._\n\n**Link** — A connection to another page.\n_Follow the link in the email._\n\n**Video** — A moving image with sound.\n_Watch the educational video._\n\n**Audio** — The sound part of a file.\n_Listen to the audio track._\n\n**Save** — Keeping your digital work.\n_Save your document before closing._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
