INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c8d50ce6-7b74-5f7f-b54c-a44a2a329b5a', '89124af7-a970-55dd-b26e-f3d4f6728c4c', 'text', 'Vocabulary', '{"text": "## Completing Assignments\n\n**Task** — A specific piece of work.\n_Finish this task in ten minutes._\n\n**Project** — A larger work over time.\n_Our project is about geography._\n\n**Deadline** — The time when work must end.\n_The deadline is tomorrow._\n\n**Submit** — Giving your work to the teacher.\n_Submit your work by email._\n\n**Draft** — The first version of a paper.\n_Write a draft of your story._\n\n**Edit** — Correcting your own work.\n_Edit your sentences for mistakes._\n\n**Complete** — Finished all parts.\n_My work is now complete._\n\n**Grade** — The score you hope for.\n_I want a high grade._\n\n**Result** — The outcome of the work.\n_The result is very good._\n\n**Hard** — Requiring much effort.\n_This project was very hard._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
