INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('3dcff32c-9219-5026-86db-83c1f33ded22', '1f94af98-d5c5-54bc-868a-a87c51860f51', 'text', 'Vocabulary', '{"text": "## Classroom Interaction\n\n**Explain** — To tell how something works.\n_Please explain the new rule._\n\n**Question** — A sentence asking for help.\n_I have a question, teacher._\n\n**Answer** — The reply to a question.\n_Give the correct answer, please._\n\n**Discuss** — Talking about a topic.\n_Discuss the ideas with friends._\n\n**Agree** — Having the same opinion.\n_Do you agree with me?_\n\n**Idea** — A thought or plan.\n_That is a great idea!_\n\n**Raise** — Moving your hand up.\n_Raise your hand to talk._\n\n**Listen** — Paying attention to sound.\n_Listen to your classmate''s idea._\n\n**Share** — Telling others your thoughts.\n_Share your story with the class._\n\n**Polite** — Using nice, respectful language.\n_It is polite to say please._\n"}', 0, NOW(), NOW())
