VALUES ('cb9f294c-7c7d-5dd5-b8fb-1e13f4d4dd3b', 'aba2cee2-d65f-5e24-ab70-942ffd237ea9', 'text', 'Vocabulary', '{"text": "## Feedback and Correction\n\n**Feedback** — Advice on how to improve.\n_The teacher gave good feedback._\n\n**Mistake** — Something you did wrong.\n_Do not worry about this mistake._\n\n**Fix** — To correct a mistake.\n_Fix your spelling errors._\n\n**Better** — An improvement.\n_Your English is better today._\n\n**Practice** — Doing something many times.\n_Practice your speaking every day._\n\n**Progress** — Moving forward in learning.\n_You are making good progress._\n\n**Again** — One more time.\n_Please say that again._\n\n**Clear** — Easy to understand.\n_Is my explanation clear?_\n\n**Check** — Looking for errors.\n_Check your work before submitting._\n\n**Right** — Exactly correct.\n_That answer is right._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
