INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('dd108c48-598f-5220-9d4e-e828cfe6b571', 'd7ce65a8-e397-50da-8330-1767f941ac05', 'text', 'Vocabulary', '{"text": "## Classroom Objects\n\n**Folder** — A cover for holding papers.\n_Put your work in the folder._\n\n**Stapler** — A tool to join papers.\n_Use the stapler for these pages._\n\n**Glue** — A liquid to stick things.\n_Use glue for the project._\n\n**Scissors** — A tool for cutting paper.\n_Be careful with the scissors._\n\n**Marker** — A thick colored pen.\n_Use a red marker for titles._\n\n**Highlighter** — A bright pen to mark text.\n_Use a highlighter for new words._\n\n**Backpack** — A bag carried on the back.\n_Put your books in your backpack._\n\n**Case** — A box for pens/pencils.\n_Where is your pencil case?_\n\n**Dictionary** — A book for meanings.\n_Use the dictionary for new words._\n\n**Map** — A visual guide of places.\n_Find Tajikistan on the map._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
