INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('670263ce-34a8-5034-a657-2b0ac4d34bb2', '40026882-b50e-5c2e-ab57-93d93d2444da', 'text', 'Vocabulary', '{"text": "## School Facilities\n\n**Cafeteria** — Where students eat lunch.\n_I will see you in the cafeteria._\n\n**Laboratory** — A place for science experiments.\n_We have science in the laboratory._\n\n**Gym** — A place for sports/exercise.\n_The gym is on the first floor._\n\n**Office** — Where the school leaders work.\n_Go to the office for help._\n\n**Library** — A quiet room for books.\n_The library is very quiet._\n\n**Corridor** — The long hall between rooms.\n_Do not run in the corridor._\n\n**Exit** — The door used for leaving.\n_Find the nearest exit._\n\n**Toilet** — The restroom area.\n_Where is the toilet, please?_\n\n**Playground** — An outdoor area for play.\n_We go to the playground._\n\n**Area** — A specific part of the school.\n_This is the study area._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
