INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('9536b250-1bee-5457-b3d5-70fc3440f63d', '33a0f446-3062-5982-929c-723987c7be37', 'text', 'Vocabulary', '{"text": "## Feelings About School\n\n**Happy** — Feeling glad about school.\n_I am happy to be here._\n\n**Tired** — Needing rest after study.\n_I am a little tired today._\n\n**Proud** — Feeling good about your work.\n_I am proud of your work._\n\n**Excited** — Feeling very happy/ready.\n_I am excited for the lesson._\n\n**Nervous** — Feeling worried about a test.\n_Do not be nervous today._\n\n**Bored** — Having nothing interesting to do.\n_The lesson is not boring._\n\n**Like** — Enjoying the school environment.\n_I like my new teacher._\n\n**Love** — Feeling very positive about something.\n_I love learning languages._\n\n**Hope** — Wishing for good results.\n_I hope to get an ''A''._\n\n**Relaxed** — Being calm and peaceful.\n_I feel relaxed in class._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
