VALUES ('fe69d043-d146-5221-ab6e-19968b8f33d1', '68ec6a44-ed6a-51e6-9673-56e0b8450a62', 'text', 'Vocabulary', '{"text": "## Closing the Lesson\n\n**Goodbye** — The parting greeting.\n_Goodbye, see you tomorrow._\n\n**Tomorrow** — The day after today.\n_See you again tomorrow._\n\n**Soon** — In a short while.\n_I will see you soon._\n\n**Clean** — Making your desk tidy.\n_Clean your desk before you go._\n\n**Pack** — Putting items in your bag.\n_Pack your pens and books._\n\n**Ready** — Prepared to leave.\n_Are you ready to go?_\n\n**Homework** — Work to do later.\n_Don''t forget your homework._\n\n**Work** — Effort done today.\n_Great work in class today._\n\n**Thank** — Showing gratitude.\n_Thank you for the lesson._\n\n**Finish** — The end of the class.\n_We finish our lesson now._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
