INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('84c06079-647a-516d-8e4f-ce776dd9daac', 'c179ab24-984d-5143-9c63-f990e6211487', 'text', 'Vocabulary', '{"text": "## Applying to School\n\n**Apply** — Sending papers to start school.\n_I want to apply to this school._\n\n**Form** — Paper with questions to answer.\n_Please fill out this application form._\n\n**Document** — An official paper (ID, grades).\n_Do you have your school documents?_\n\n**Grade** — The marks from previous school.\n_My school grades are very good._\n\n**Send** — To mail or email papers.\n_I will send my form today._\n\n**Fee** — Money paid for schooling.\n_What is the tuition fee?_\n\n**Deadline** — The last day to apply.\n_The deadline is on Monday._\n\n**Office** — Where you submit papers.\n_Go to the admissions office._\n\n**Letter** — A formal request or message.\n_I need a recommendation letter._\n\n**Ready** — Prepared for the process.\n_Are your papers ready?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
