INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('7a6a2af8-7b9c-5927-b510-bed0d57a0556', 'a56cae41-7137-5a2c-95aa-88757f98f2a1', 'text', 'Vocabulary', '{"text": "## Degrees and Levels\n\n**Degree** — An official title from a university.\n_I want to get a university degree._\n\n**Level** — A stage of learning (A1, A2, etc.).\n_My English level is A1._\n\n**Certificate** — A paper showing you finished a course.\n_I need a certificate for my work._\n\n**Diploma** — A document showing graduation.\n_He received his high school diploma._\n\n**University** — A place for high-level study.\n_She studies at the university._\n\n**College** — A place for specialized study.\n_I want to go to a technical college._\n\n**Class** — A specific group you study in.\n_I am in an advanced class._\n\n**Course** — A series of lessons.\n_This English course is ten weeks._\n\n**Graduate** — To finish a school program.\n_I will graduate next year._\n\n**Scholar** — A very good student.\n_She is a top scholar._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
