INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('be0d52f5-2e31-5f36-857d-9195007f84df', '7656213c-307c-5640-8ca2-c28ce75cb92f', 'text', 'Vocabulary', '{"text": "## Scholarships and Funding\n\n**Scholarship** — Money for school given by others.\n_She won a scholarship for her studies._\n\n**Money** — Funds needed for costs.\n_School costs a lot of money._\n\n**Pay** — To give money for service.\n_I will pay the school fee._\n\n**Free** — No money required.\n_Is this course free?_\n\n**Fund** — Money saved for a project.\n_They have a fund for students._\n\n**Help** — Financial assistance.\n_Can the school help me?_\n\n**Support** — Helping a student succeed.\n_They offer a lot of support._\n\n**Save** — Keeping money for later.\n_I save money for my classes._\n\n**Cost** — The price of something.\n_What is the total cost?_\n\n**Apply** — Asking for the money.\n_I will apply for the scholarship._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
