INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('ef09777d-b628-595f-b169-92340a5f8580', '4698aef5-1612-5b6d-9b52-ebabda632605', 'text', 'Vocabulary', '{"text": "## Research and Academic Skills\n\n**Research** — Looking for information about a topic.\n_I do research for my project._\n\n**Topic** — The subject you study.\n_My topic is technology._\n\n**Source** — Where you find information.\n_Find a good source for facts._\n\n**Fact** — Something true.\n_This book has many facts._\n\n**Note** — Writing down key ideas.\n_Take a note of the date._\n\n**Summary** — A short version of information.\n_Write a summary of the book._\n\n**Report** — A formal paper you write.\n_I must write a science report._\n\n**Analysis** — Looking at details.\n_The analysis is very deep._\n\n**Idea** — Your own thought.\n_Share your idea with me._\n\n**Prove** — Showing something is true.\n_I can prove my point._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
