INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c07ef47e-9bea-52d5-8634-8891fa6517cf', '2523e34c-7404-5041-bd71-08f968e4f811', 'text', 'Vocabulary', '{"text": "## Presentations\n\n**Present** — Showing work to others.\n_I will present my work today._\n\n**Speech** — Talking to a group.\n_His speech was very good._\n\n**Slide** — Digital pages on a screen.\n_I have ten slides to show._\n\n**Show** — Displaying something.\n_Show the class your work._\n\n**Explain** — Giving more info.\n_Explain your ideas clearly._\n\n**Talk** — Speaking about a topic.\n_Talk to the audience, please._\n\n**Listen** — What the others do.\n_Please listen to the presentation._\n\n**Question** — Asking about the work.\n_Does anyone have a question?_\n\n**Answer** — Replying to questions.\n_Answer the question carefully._\n\n**Confident** — Feeling ready to perform.\n_Be confident when you speak._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
