INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('6decae9b-518d-5d9c-b006-a81717ce19a0', '51dfd6ed-451a-57fa-a7cd-98d039429737', 'text', 'Vocabulary', '{"text": "## Study Groups\n\n**Group** — Working with others.\n_Our study group meets today._\n\n**Meet** — Coming together.\n_Where shall we meet?_\n\n**Plan** — Organizing the time.\n_We plan the study session._\n\n**Share** — Using info together.\n_Share your notes with the group._\n\n**Discuss** — Talking about the work.\n_We discuss the difficult parts._\n\n**Help** — Giving support.\n_Help your friend understand._\n\n**Teach** — Helping others learn.\n_I can teach you this rule._\n\n**Time** — Deciding when to meet.\n_What time is the meeting?_\n\n**Place** — Where the meeting is.\n_The library is a good place._\n\n**Together** — As a group.\n_We study better together._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
