INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('2b68effb-6c9d-5c81-adae-c0398045e3d5', '9e7f2fd5-9065-54aa-84ee-241a5214c276', 'text', 'Vocabulary', '{"text": "## Exams and Assessment\n\n**Exam** — A big test.\n_The final exam is coming._\n\n**Prepare** — Getting ready.\n_I prepare for the exam daily._\n\n**Review** — Looking at old work.\n_Review your notes again._\n\n**Score** — The points you get.\n_My score was very high._\n\n**Pass** — Doing well enough.\n_I want to pass this exam._\n\n**Fail** — Not doing well.\n_Do not fail the test._\n\n**Result** — The final grade.\n_I wait for the result._\n\n**Stress** — Feeling worried.\n_Do not have too much stress._\n\n**Calm** — Being quiet/relaxed.\n_Stay calm during the exam._\n\n**Succeed** — To achieve the result.\n_I will succeed today._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
