VALUES ('8489099e-5609-5fee-a0c7-a532e9e9df7c', '07ebd6df-6c2c-5c6f-bd56-58691b911ad9', 'text', 'Vocabulary', '{"text": "## Teacher Interactions\n\n**Teacher** — The instructor.\n_The teacher explains the lesson._\n\n**Office** — The teacher''s room.\n_Go to the teacher''s office._\n\n**Advice** — Helpful words.\n_I need your advice, teacher._\n\n**Guide** — Showing the way.\n_Please guide me in my study._\n\n**Support** — Helping you learn.\n_Thank you for your support._\n\n**Letter** — Recommendation document.\n_Can you write me a letter?_\n\n**Meet** — Having a talk.\n_Can we meet tomorrow?_\n\n**Question** — Seeking help.\n_I have a question about the test._\n\n**Respect** — Acting nicely to teachers.\n_Always show respect._\n\n**Thanks** — Being grateful.\n_Thanks for the help, teacher._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
