INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d3d74f2f-7eb6-5ff0-bee5-b86dfe41ac51', 'fca2e2c2-37ab-5206-83e0-635b154acf49', 'text', 'Vocabulary', '{"text": "## Graduating and Moving On\n\n**Graduate** — Finishing your studies.\n_I will graduate next month!_\n\n**Party** — A celebration.\n_The graduation party is fun._\n\n**Future** — The next part of life.\n_What is your plan for the future?_\n\n**Goal** — Looking for a job.\n_My goal is a new job._\n\n**Happy** — Feeling great about the finish.\n_I am happy to finish school._\n\n**Proud** — Feeling good about your work.\n_I am proud of my degree._\n\n**Work** — Moving to a career.\n_I start my work soon._\n\n**Thank** — Acknowledging help.\n_Thank you for the support._\n\n**Again** — Doing more later.\n_I will study again one day._\n\n**Finish** — Ending one part.\n_I finish this stage now._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
