INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('37d1b581-f909-5c62-addf-3c68f7086168', 'd3bc9d82-8037-551e-85c9-a61db7d0d691', 'text', 'Vocabulary', '{"text": "## Language Skills\n\n**Vocabulary** — The collection of words you know.\n_My English vocabulary is growing._\n\n**Pronunciation** — How you say words.\n_Good pronunciation is important._\n\n**Listen** — Hearing and understanding.\n_Listen to the English audio._\n\n**Speak** — Using your voice to talk.\n_Can you speak more slowly?_\n\n**Write** — Using a pen or keyboard.\n_Write a short paragraph today._\n\n**Read** — Understanding text.\n_I like to read stories._\n\n**Grammar** — The rules of language.\n_I study grammar for one hour._\n\n**Practice** — Doing something repeatedly to improve.\n_Practice makes you better._\n\n**Fluency** — Speaking smoothly.\n_I want to gain fluency._\n\n**Master** — Learning something perfectly.\n_I want to master this level._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
