INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e77c8a53-bb8f-5f75-ad9a-ba46d72cd023', '7d4bf7b5-8bdf-5ea0-ba6a-f36464da658a', 'text', 'Vocabulary', '{"text": "## Learning Styles\n\n**Visual** — Learning by seeing things.\n_I am a visual learner._\n\n**Listen** — Learning by hearing.\n_I learn by listening._\n\n**Active** — Doing things to learn.\n_I am an active student._\n\n**Group** — Working with other people.\n_I like to work in a group._\n\n**Alone** — Working by yourself.\n_I study better when I am alone._\n\n**Method** — A way of doing something.\n_What is your favorite method?_\n\n**Simple** — Not complex.\n_The simple method is best._\n\n**Try** — To attempt an action.\n_Try to study every day._\n\n**Focus** — Giving all your attention.\n_Focus on your English work._\n\n**Smart** — Intelligent or clever.\n_You are a smart student._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
