INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('4d65a714-ed00-5a81-8ecf-2b648e3ca98b', 'b3828b86-e10d-513b-b83f-365233d9af37', 'text', 'Vocabulary', '{"text": "## Educational Technology\n\n**App** — A small program on a phone.\n_Download this English learning app._\n\n**Digital** — Using computer technology.\n_We use digital books now._\n\n**Platform** — An online system for learning.\n_This is a great learning platform._\n\n**Screen** — The glass you look at.\n_The screen is very clear._\n\n**Keyboard** — Used for typing.\n_My keyboard is very fast._\n\n**Mouse** — Used to click on a screen.\n_Use your mouse to click._\n\n**Connect** — Joining to the internet.\n_Connect to the Wi-Fi, please._\n\n**Login** — Accessing your account.\n_Enter your login to start._\n\n**Update** — Making something current.\n_Update your profile today._\n\n**Data** — Information saved online.\n_Save your data in the cloud._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
