INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('aff1f87f-fba7-5fa7-a201-5973efa7247d', 'd839011d-b728-556a-90b3-860c85be098e', 'text', 'Vocabulary', '{"text": "## Teacher-Student Dynamic\n\n**Coach** — A teacher who guides you.\n_My English coach is great._\n\n**Guide** — Leading the way.\n_She will guide my learning._\n\n**Correct** — Fixing a mistake.\n_The teacher will correct me._\n\n**Explain** — Making things clear.\n_Please explain the rule again._\n\n**Encourage** — Helping you feel confident.\n_Teachers encourage their students._\n\n**Respect** — Being kind and polite.\n_We show respect to teachers._\n\n**Feedback** — Notes on your work.\n_I like your teacher''s feedback._\n\n**Mentor** — A wise, helpful teacher.\n_He is a good mentor._\n\n**Trust** — Believing in your teacher.\n_I trust my teacher''s help._\n\n**Team** — Teacher and student together.\n_We are a good team._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
