INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('177eb47b-6837-55d9-9092-13ff9591cc06', '9252baf1-2529-582a-8b82-a0b28f59b991', 'text', 'Vocabulary', '{"text": "## Classroom Manners\n\n**Polite** — Showing good behavior.\n_Be polite to your friends._\n\n**Kindly** — In a nice way.\n_Please speak kindly today._\n\n**Quiet** — Keeping noise low.\n_It is quiet in the room._\n\n**Wait** — Being patient.\n_Wait for your turn, please._\n\n**Raise** — Moving your hand up.\n_Raise your hand to speak._\n\n**Listen** — Paying attention.\n_Listen when others talk._\n\n**Thanks** — Saying gratitude.\n_Say thanks for the help._\n\n**Sorry** — Apologizing for mistakes.\n_Say sorry if you are late._\n\n**Share** — Giving items to others.\n_Share your pens today._\n\n**Kind** — Helpful and friendly.\n_Be kind in the class._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
