INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('50a944ca-9c2a-5e3f-8f28-8d23d5ecdb41', '6974dbe2-6260-5e9b-a6d8-d5a1dd39a198', 'text', 'Vocabulary', '{"text": "## Advanced Study Concepts\n\n**Concept** — A general idea.\n_This concept is very new._\n\n**Logic** — Thinking clearly.\n_Math requires good logic._\n\n**Reason** — Why something happens.\n_What is the reason here?_\n\n**Theory** — A set of ideas.\n_I study the history theory._\n\n**Method** — The way you study.\n_This method works for me._\n\n**Process** — A series of steps.\n_The process is quite long._\n\n**Detail** — A small part of something.\n_Look at every small detail._\n\n**Create** — To make something new.\n_Create a new study plan._\n\n**Solve** — Finding the answer.\n_Solve the problem now._\n\n**Answer** — The final result.\n_The answer is very clear._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
