VALUES ('537e00ad-ccf5-5f75-a927-181e84f5b48a', '274b6c7f-0c45-5f4d-9e45-af2f4e8572be', 'text', 'Vocabulary', '{"text": "## School Atmosphere\n\n**Atmosphere** — The feeling in a room.\n_The school atmosphere is good._\n\n**Busy** — Having a lot to do.\n_The school is very busy._\n\n**Calm** — Quiet and peaceful.\n_I feel calm while studying._\n\n**Friendly** — Kind and nice.\n_My classmates are friendly._\n\n**Bright** — Lots of light.\n_The classroom is very bright._\n\n**Clean** — Not dirty.\n_A clean room is better._\n\n**Large** — Not small.\n_Our school is quite large._\n\n**Modern** — New and current.\n_We have modern computers._\n\n**Fun** — Enjoyable experience.\n_Learning here is very fun._\n\n**Great** — Very good.\n_This is a great school._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
