INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c3ebaf17-0584-5be0-a092-69812fe616d3', 'c60d9249-5335-5b5b-98bb-f086241e4f68', 'text', 'Vocabulary', '{"text": "## Evaluation and Self-Reflection\n\n**Reflection** — Thinking about your work.\n_My reflection helps me learn._\n\n**Improve** — Getting better.\n_I want to improve daily._\n\n**Goal** — Target you want.\n_Did you reach your goal?_\n\n**Success** — Getting what you wanted.\n_Success takes a lot of work._\n\n**Mistake** — Error you made.\n_Learn from every mistake._\n\n**Strong** — Having good skill.\n_My writing is very strong._\n\n**Weak** — Needing more work.\n_My grammar is a bit weak._\n\n**Study** — Effort.\n_More study makes me better._\n\n**Change** — Doing something differently.\n_Change your study plan._\n\n**Better** — Improved status.\n_I feel better at English._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
