INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('b2f1308b-92ca-5789-9384-be83620fda80', '6142b998-842f-5c14-9a17-95dd7ce1f29d', 'text', 'Vocabulary', '{"text": "## Lifelong Learning\n\n**Lifelong** — During your whole life.\n_Learning is a lifelong goal._\n\n**Daily** — Every single day.\n_I study my English daily._\n\n**Skill** — A thing you can do.\n_English is a useful skill._\n\n**Future** — Time ahead.\n_Think about your bright future._\n\n**Growth** — Getting bigger/better.\n_I focus on personal growth._\n\n**Always** — At all times.\n_Always try to learn more._\n\n**Learn** — Getting knowledge.\n_Never stop trying to learn._\n\n**Read** — Getting information.\n_Read books for your growth._\n\n**Help** — Supporting others.\n_Help others learn as well._\n\n**Success** — The result of growth.\n_Success follows hard work._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
