INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('087a744f-9845-5657-ab2f-5ebc4221f1f1', 'dd694812-23b2-5f5d-bcf5-8210361b4af8', 'text', 'Vocabulary', '{"text": "## Final Review and Celebration\n\n**Review** — Looking at everything.\n_Do a review of all tracks._\n\n**Celebrate** — Having fun for success.\n_Let us celebrate our success._\n\n**Happy** — Feeling glad.\n_I am so happy today!_\n\n**Proud** — Good feeling about work.\n_You should be very proud._\n\n**Finish** — Reaching the end.\n_We finish this goal now._\n\n**Ready** — Prepared for next.\n_Are you ready for more?_\n\n**Great** — Awesome work.\n_You did a great job._\n\n**Work** — The effort used.\n_Your work was very good._\n\n**Future** — Next steps.\n_What is in your future?_\n\n**Together** — Combined effort.\n_We worked very well together._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
